window.CFA_LESSONS=(window.CFA_LESSONS||[]).concat([{"module_id":"CFA26-08-03","title":"Investments in Private Capital: Equity and Debt","version":"2026","source_basis":[{"source_id":"CFAI","pdf_pages":[73,100],"relation":"primary"},{"source_id":"Kaplan","pdf_pages":[28,34],"relation":"supplementary"},{"source_id":"SAPP","pdf_pages":[35,60],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-08-03-LOS01","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Giải thích private equity và đặc điểm đầu tư của loại hình này.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S01-01","S01-02","S01-03","S01-04","S01-05","S01-06","S01-07"],"formula_ids":["F01-01","F01-02","F01-03"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V8_Alts_ONLINE.pdf","pdf_page":78},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":28},"SAPP_2026":{"file":"SAPP Alternative Investments.pdf","pdf_page":35}},"missing_items":[]},{"los_id":"CFA26-08-03-LOS02","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Giải thích private debt và đặc điểm đầu tư của loại hình này.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S02-01","S02-02","S02-03","S02-04","S02-05","S02-06","S02-07"],"formula_ids":["F02-01","F02-02"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V8_Alts_ONLINE.pdf","pdf_page":87},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":31},"SAPP_2026":{"file":"SAPP Alternative Investments.pdf","pdf_page":51}},"missing_items":[]},{"los_id":"CFA26-08-03-LOS03","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Mô tả lợi ích đa dạng hóa mà private capital có thể mang lại.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S03-01","S03-02","S03-03","S03-04","S03-05","S03-06","S03-07"],"formula_ids":["F03-01","F03-02"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V8_Alts_ONLINE.pdf","pdf_page":93},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":31},"SAPP_2026":{"file":"SAPP Alternative Investments.pdf","pdf_page":56}},"missing_items":[]}],"sections":[{"heading_vi":"Khái niệm private equity","body_vi":"Private equity là vốn chủ sở hữu cung cấp ngoài thị trường niêm yết, gồm đầu tư vào doanh nghiệp tư nhân hoặc thâu tóm doanh nghiệp niêm yết để đưa về tư nhân. Nhà đầu tư có thể nắm quyền kiểm soát hoặc phần vốn thiểu số; khả năng định giá, quản trị và thoái vốn quyết định kết quả, không thể chỉ dựa vào giá cổ phiếu tham chiếu.","id":"S01-01","los_ids":["CFA26-08-03-LOS01"]},{"heading_vi":"Venture capital qua các giai đoạn","body_vi":"Venture capital hỗ trợ doanh nghiệp có tiềm năng tăng trưởng mạnh từ seed, startup, early-stage tới later-stage. Doanh thu và dòng tiền ban đầu có thể âm, xác suất thất bại lớn, đổi lại một số khoản đầu tư thành công có thể tạo giá trị rất cao. Khả năng pha loãng và nhu cầu nhiều vòng gọi vốn là rủi ro cốt lõi.","id":"S01-02","los_ids":["CFA26-08-03-LOS01"]},{"heading_vi":"Growth và developmental capital","body_vi":"Growth capital hoặc minority equity thường hỗ trợ doanh nghiệp đã hình thành sản phẩm, có doanh thu và muốn mở rộng thị trường, tái cấu trúc hoặc thực hiện M&A. Nhà đầu tư có thể không kiểm soát toàn bộ hoạt động nên cần điều khoản bảo vệ cổ đông thiểu số, quyền thông tin và cơ chế thoái vốn phù hợp.","id":"S01-03","los_ids":["CFA26-08-03-LOS01"]},{"heading_vi":"Leveraged buyout và vai trò nợ vay","body_vi":"LBO sử dụng đáng kể nợ cùng vốn chủ để mua doanh nghiệp có dòng tiền tương đối ổn định. Nếu cải thiện EBITDA và trả bớt nợ, equity value khi thoái vốn có thể tăng mạnh; ngược lại lãi vay, covenant breach và suy giảm EBITDA có thể khiến vốn chủ chịu tổn thất lớn. MBO do nhóm quản lý hiện hữu tham gia, MBI có nhóm quản lý bên ngoài.","id":"S01-04","los_ids":["CFA26-08-03-LOS01"]},{"heading_vi":"Nguồn tạo giá trị private equity","body_vi":"Lợi nhuận có thể đến từ tăng trưởng doanh thu, cải thiện biên lợi nhuận, sử dụng tài sản hiệu quả, giảm đòn bẩy sau giao dịch và thay đổi EV/EBITDA multiple khi thoái vốn. Cần tách tăng hiệu quả hoạt động khỏi việc mở rộng multiple do thị trường vì multiple expansion không được bảo đảm.","id":"S01-05","los_ids":["CFA26-08-03-LOS01"]},{"heading_vi":"Chiến lược thoái vốn","body_vi":"Các lối thoát gồm bán cho doanh nghiệp chiến lược (trade sale), bán cho quỹ PE khác (secondary sale), IPO/direct listing, tái cấp vốn nhận cổ tức, hoặc thanh lý nếu thất bại. Mỗi phương án có phí, thời gian, rủi ro định giá và điều kiện thị trường khác nhau; giá trị NAV chưa phải dòng tiền thực hiện.","id":"S01-06","los_ids":["CFA26-08-03-LOS01"]},{"heading_vi":"Đặc điểm hiệu quả và rủi ro PE","body_vi":"Private equity có kỳ hạn dài, capital calls, thông tin không công khai, chi phí quản lý cao và khó định giá giữa các lần thoái vốn. Phân tích cần xét vintage year, sector, chính sách dùng nợ, phương pháp ghi NAV và mức phí. Tăng đòn bẩy có thể làm equity IRR hấp dẫn nhưng không xóa bỏ rủi ro kinh doanh và thanh khoản.","id":"S01-07","los_ids":["CFA26-08-03-LOS01"]},{"heading_vi":"Private debt là gì","body_vi":"Private debt là tín dụng được cung cấp trực tiếp hoặc qua quỹ cho người vay ngoài thị trường phát hành nợ công khai. Người cho vay phải tự thẩm định dòng tiền, collateral, quyền ưu tiên và covenant; rủi ro thanh khoản thường cao vì khoản vay không được giao dịch thường xuyên như trái phiếu niêm yết.","id":"S02-01","los_ids":["CFA26-08-03-LOS02"]},{"heading_vi":"Direct lending và senior secured debt","body_vi":"Direct lending bao gồm khoản vay trực tiếp cho doanh nghiệp với kỳ hạn, lãi suất thường thả nổi và các covenant được đàm phán. Senior secured loans ưu tiên thu hồi từ tài sản bảo đảm trước chủ nợ cấp dưới, nhưng mức độ bảo vệ thực tế vẫn phụ thuộc tài sản, tính pháp lý và khả năng thực thi khi vỡ nợ.","id":"S02-02","los_ids":["CFA26-08-03-LOS02"]},{"heading_vi":"Leveraged lending và unitranche","body_vi":"Leveraged loans tài trợ bên vay có đòn bẩy đáng kể, thường chịu rủi ro suy giảm khả năng trả nợ khi EBITDA giảm. Unitranche kết hợp nhiều lớp rủi ro nợ vào một khoản vay có hợp đồng và lãi suất tổng hợp; thỏa thuận giữa các nhà cho vay có thể phân chia thứ tự thu hồi nội bộ khác nhau.","id":"S02-03","los_ids":["CFA26-08-03-LOS02"]},{"heading_vi":"Mezzanine debt và quyền chuyển đổi","body_vi":"Mezzanine financing nằm dưới nợ senior về thứ tự ưu tiên, thường có coupon cao hơn và có thể kèm warrants hoặc công cụ chuyển đổi. Bên cho vay nhận thêm phần thưởng tiềm năng khi doanh nghiệp phát triển, nhưng recovery khi vỡ nợ thường kém hơn senior secured debt.","id":"S02-04","los_ids":["CFA26-08-03-LOS02"]},{"heading_vi":"Venture debt và nợ doanh nghiệp tăng trưởng","body_vi":"Venture debt cấp cho doanh nghiệp tăng trưởng, đôi khi có VC backing và tài sản hữu hình hạn chế. Khoản vay có thể bao gồm lãi trả tiền, phí cuối kỳ và warrants, bổ trợ vòng equity nhưng làm tăng nghĩa vụ trả nợ; không mặc định công ty khởi nghiệp phù hợp với nợ vì doanh thu tăng.","id":"S02-05","los_ids":["CFA26-08-03-LOS02"]},{"heading_vi":"Distressed debt và DIP financing","body_vi":"Distressed debt là mua nợ của doanh nghiệp đang khó khăn với giá chiết khấu; lợi nhuận phụ thuộc giá thu hồi, tái cơ cấu và diễn biến pháp lý. Debtor-in-possession (DIP) financing có thể cung cấp vốn trong thủ tục phá sản với quyền ưu tiên theo quy định từng nơi; rủi ro pháp lý vẫn đáng kể.","id":"S02-06","los_ids":["CFA26-08-03-LOS02"]},{"heading_vi":"Các rủi ro đặc thù private debt","body_vi":"Cần xem xét PD, LGD, tỷ lệ bao phủ tài sản bảo đảm, covenant, lãi suất biến động, hạn chế chuyển nhượng và thời gian thực thi quyền chủ nợ. Lãi suất coupon cao chưa đủ chứng minh đầu tư tốt nếu xác suất vỡ nợ hoặc tổn thất khi vỡ nợ lớn.","id":"S02-07","los_ids":["CFA26-08-03-LOS02"]},{"heading_vi":"Lý thuyết đa dạng hóa private capital","body_vi":"Private equity và private debt có nguồn sinh lợi khác nhau so với chứng khoán niêm yết, ví dụ tái cấu trúc doanh nghiệp, lãi suất vay tư nhân hoặc phát triển công ty sớm. Nếu tương quan với tài sản truyền thống chưa đạt +1, kết hợp tài sản có thể giảm biến động danh mục ở một số điều kiện.","id":"S03-01","los_ids":["CFA26-08-03-LOS03"]},{"heading_vi":"Tương quan phụ thuộc chu kỳ và loại chiến lược","body_vi":"Venture capital, buyout, distressed debt và direct lending không có cùng mức độ tương quan với cổ phiếu/trái phiếu. Trong khủng hoảng dòng tiền và thanh khoản, beta kinh tế có thể tăng; không nên dùng tương quan lịch sử thấp như bằng chứng tài sản có khả năng phòng hộ mọi cú sốc.","id":"S03-02","los_ids":["CFA26-08-03-LOS03"]},{"heading_vi":"Valuation smoothing và kết quả quan sát","body_vi":"NAV private capital được ghi nhận định kỳ từ mô hình hoặc thẩm định; do độ trễ, chuỗi lợi suất công bố thường có tương quan với thị trường thấp hơn quan hệ kinh tế thực tế. Phân tích danh mục cần cân nhắc việc làm mượt dữ liệu trước khi sử dụng historical correlation để đo lợi ích đa dạng hóa.","id":"S03-03","los_ids":["CFA26-08-03-LOS03"]},{"heading_vi":"Vintage year diversification","body_vi":"Vintage year là năm quỹ bắt đầu triển khai đầu tư, có ý nghĩa vì điều kiện lãi suất, định giá và tăng trưởng doanh nghiệp thay đổi giữa các chu kỳ. Trải cam kết vốn qua nhiều vintage có thể giảm rủi ro đầu tư cùng lúc tại đỉnh định giá, nhưng không loại bỏ rủi ro hệ thống.","id":"S03-04","los_ids":["CFA26-08-03-LOS03"]},{"heading_vi":"Diversification theo ngành, vùng và nhà quản lý","body_vi":"Phân bổ qua nhiều ngành, địa bàn, loại tài sản và GP làm giảm phụ thuộc vào một doanh nghiệp hoặc một phương pháp thoái vốn. Tuy nhiên nhiều quỹ có thể mua các doanh nghiệp giống nhau hoặc cùng vay nợ từ một nguồn, gây tập trung kinh tế ẩn dù số chứng chỉ quỹ tăng.","id":"S03-05","los_ids":["CFA26-08-03-LOS03"]},{"heading_vi":"Thanh khoản và capital-call risk ở cấp danh mục","body_vi":"Khi thị trường suy giảm, LP có thể đồng thời bị gọi vốn trong khi tài sản niêm yết mất giá, khiến tỷ trọng private capital trong tổng danh mục tăng ngoài ý muốn (denominator effect). Do đó đa dạng hóa theo thống kê không thay thế kế hoạch duy trì tài sản thanh khoản để đáp ứng nghĩa vụ góp vốn.","id":"S03-06","los_ids":["CFA26-08-03-LOS03"]},{"heading_vi":"Đánh giá lợi ích sau phí và rủi ro","body_vi":"Lợi ích của private capital phải được so sánh bằng net returns, rủi ro đòn bẩy, tổn thất tín dụng và tính thanh khoản. Một khoản đầu tư có tương quan lịch sử thấp nhưng phí cao, định giá thiếu minh bạch và hạn chế thoái vốn vẫn có thể làm hồ sơ rủi ro tổng thể kém đi.","id":"S03-07","los_ids":["CFA26-08-03-LOS03"]}],"formulae":[{"expression":"EV = EBITDA × EV/EBITDA multiple","variables":["EBITDA chuẩn hóa và hệ số từ giao dịch so sánh."],"assumptions":["Ước tính nhanh; phải điều chỉnh nợ, tiền mặt và khác biệt doanh nghiệp."],"id":"F01-01","los_ids":["CFA26-08-03-LOS01"]},{"expression":"Equity value = Enterprise value − Net debt","variables":["Net debt = nợ chịu lãi − tiền mặt có thể sử dụng."],"assumptions":["Đơn giản hóa; bỏ qua lợi ích cổ đông thiểu số và các điều chỉnh thương vụ."],"id":"F01-02","los_ids":["CFA26-08-03-LOS01"]},{"expression":"Equity MOIC = Equity proceeds at exit / Initial equity invested","variables":["Cả tử/mẫu xác định cùng cơ sở phí."],"assumptions":["Không phản ánh thời gian và các đợt rót vốn thêm."],"id":"F01-03","los_ids":["CFA26-08-03-LOS01"]},{"expression":"Expected credit loss ≈ PD × LGD × EAD","variables":["PD xác suất vỡ nợ, LGD tỷ lệ tổn thất khi vỡ nợ, EAD dư nợ tại thời điểm vỡ nợ."],"assumptions":["Mô hình một kỳ giản lược, không chiết khấu và chưa xét tương quan rủi ro."],"id":"F02-01","los_ids":["CFA26-08-03-LOS02"]},{"expression":"Debt / EBITDA = Tổng dư nợ chịu lãi / EBITDA","variables":["Dư nợ và EBITDA trên cơ sở so sánh thích hợp."],"assumptions":["Có thể loại trừ tiền mặt hoặc dùng net leverage khi đề quy định."],"id":"F02-02","los_ids":["CFA26-08-03-LOS02"]},{"expression":"σp² = w1²σ1² + w2²σ2² + 2w1w2σ1σ2ρ12","variables":["w là trọng số, σ là độ lệch chuẩn, ρ là tương quan giữa hai khoản đầu tư."],"assumptions":["Dùng biến động kinh tế phù hợp; appraisal smoothing có thể làm σ và ρ bị thấp giả tạo."],"id":"F03-01","los_ids":["CFA26-08-03-LOS03"]},{"expression":"Incremental capital remaining = Fund commitment − Capital calls contributed","variables":["Vốn cam kết và vốn đã gọi tại cùng thời điểm."],"assumptions":["Nếu có tái gọi vốn hoặc recycling cần sửa theo hợp đồng."],"id":"F03-02","los_ids":["CFA26-08-03-LOS03"]}],"worked_examples":[{"problem":"LBO mua doanh nghiệp EV=100 triệu USD, nợ ròng lúc mua 60 triệu, bán EV=125 triệu, nợ ròng còn 45 triệu. Tính equity MOIC.","solution_steps":["Equity ban đầu = 100−60 = 40 triệu USD.","Equity khi thoái vốn = 125−45 = 80 triệu USD.","MOIC = 80/40 = 2,0×; chưa xét phí giao dịch, cổ tức và các lần góp vốn thêm."],"answer":"Equity MOIC=2,0×; giảm nợ ròng 15 triệu đóng góp vào tăng equity value.","id":"E01-01","los_ids":["CFA26-08-03-LOS01"]},{"problem":"Doanh nghiệp có EBITDA 15 triệu và exit multiple 8×, nợ ròng 50 triệu. Tính equity value.","solution_steps":["EV dự phóng = 15×8 = 120 triệu USD.","Equity value = 120−50 = 70 triệu USD.","Nếu multiple giảm còn 6× thì equity value chỉ 90−50=40 triệu, cho thấy độ nhạy với định giá."],"answer":"Equity value cơ sở 70 triệu USD, nhưng giảm multiple từ 8× xuống 6× làm giá trị giảm 30 triệu.","id":"E01-02","los_ids":["CFA26-08-03-LOS01"]},{"problem":"Khoản private debt có PD=5%, LGD=40% và EAD=10 triệu USD. Tính expected credit loss một kỳ.","solution_steps":["PD = 0,05; LGD=0,40; EAD=10 triệu.","Expected loss = 0,05×0,40×10 triệu = 0,20 triệu USD.","Khoản dự kiến này khác tổn thất thực tế trong một kịch bản riêng lẻ."],"answer":"Expected credit loss xấp xỉ 200.000 USD theo mô hình đơn kỳ đơn giản.","id":"E02-01","los_ids":["CFA26-08-03-LOS02"]},{"problem":"Doanh nghiệp có nợ 75 triệu, EBITDA 15 triệu. Tính debt/EBITDA và đánh giá khi EBITDA giảm còn 10 triệu.","solution_steps":["Leverage ban đầu = 75/15 = 5,0×.","Nếu EBITDA giảm xuống 10 triệu và dư nợ không đổi, leverage = 75/10 = 7,5×.","Tỷ lệ đòn bẩy tăng làm covenant headroom và khả năng tái cấp vốn suy giảm, dù dư nợ danh nghĩa không đổi."],"answer":"Debt/EBITDA tăng từ 5,0× lên 7,5× khi EBITDA giảm, thể hiện rủi ro tín dụng tăng.","id":"E02-02","los_ids":["CFA26-08-03-LOS02"]},{"problem":"Danh mục đầu tư 50% cổ phiếu σ20%, 50% private assets σ15%, tương quan 0,3. Tính σp trên giả định dữ liệu đáng tin.","solution_steps":["Variance = 0,25×0,2² +0,25×0,15²+2×0,5×0,5×0,2×0,15×0,3.","=0,01+0,005625+0,0045=0,020125.","σp=√0,020125≈14,186%, thấp hơn σ của cổ phiếu riêng lẻ 20%."],"answer":"Độ lệch chuẩn danh mục khoảng 14,19% với tương quan giả định 0,3; thẩm định NAV có thể làm con số bị đánh giá thấp.","id":"E03-01","los_ids":["CFA26-08-03-LOS03"]},{"problem":"LP cam kết 8 triệu USD, đã góp 5 triệu; trong khủng hoảng quỹ gọi thêm 2 triệu. Cần dự phòng tối thiểu?","solution_steps":["Cam kết chưa góp trước đợt mới = 8−5 = 3 triệu USD.","Đợt capital call được thông báo là 2 triệu nên phải sắp xếp ít nhất 2 triệu tiền thanh khoản ngay.","Sau khi thanh toán, cam kết còn lại 1 triệu, chưa kể điều khoản tái gọi vốn nếu có."],"answer":"Cần ít nhất 2 triệu USD thanh khoản cho capital call hiện tại; phần chưa góp sau call là 1 triệu.","id":"E03-02","los_ids":["CFA26-08-03-LOS03"]}],"questions":[{"stem":"Trong LBO, điều nào có thể khuếch đại lợi nhuận vốn chủ khi doanh nghiệp cải thiện EBITDA và giảm nợ?","options":["Giảm đòn bẩy sau mua và tăng enterprise value","Bảo đảm lợi nhuận bất kể dòng tiền","Tăng nợ ròng vô hạn không có rủi ro"],"correct_option":0,"explanation":"Equity exit = enterprise value − net debt; khi EV tăng và net debt giảm, vốn chủ nhận phần tăng lớn hơn tỷ lệ tăng của tổng giá trị.","id":"Q01-01","los_ids":["CFA26-08-03-LOS01"]},{"stem":"Nhà đầu tư cấp vốn cho startup chưa có dòng tiền dương, chấp nhận xác suất thất bại lớn để tìm tăng trưởng mạnh. Phù hợp nhất?","options":["Đầu tư tín phiếu kho bạc","Venture capital","Mua trái phiếu senior của chính phủ"],"correct_option":1,"explanation":"Venture capital tài trợ doanh nghiệp giai đoạn sớm, chịu rủi ro thất bại và pha loãng cao để đổi lấy cơ hội tăng trưởng lớn.","id":"Q01-02","los_ids":["CFA26-08-03-LOS01"]},{"stem":"LBO thoái vốn EV=125, nợ ròng 45, equity lúc mua40; MOIC vốn chủ?","options":["1,5×","3,0×","2,0×"],"correct_option":2,"explanation":"Equity exit = 125−45 = 80; Equity MOIC = 80/40 = 2,0× trong giả định không có đóng góp hay phân phối trung gian.","id":"Q01-03","los_ids":["CFA26-08-03-LOS01"]},{"stem":"Loại private debt nào thông thường có quyền ưu tiên trên tài sản bảo đảm cao hơn mezzanine debt?","options":["Senior secured direct lending","Nợ thứ cấp mezzanine","Cổ phần phổ thông không bảo đảm"],"correct_option":0,"explanation":"Senior secured loan được ưu tiên thanh toán trước các lớp nợ thứ cấp theo hợp đồng, song recovery vẫn phụ thuộc tài sản và pháp lý.","id":"Q02-01","los_ids":["CFA26-08-03-LOS02"]},{"stem":"Private debt PD=5%, LGD=40%, EAD=10 triệu có expected loss?","options":["2 triệu","0,2 triệu","0,02 triệu"],"correct_option":1,"explanation":"Expected loss = 0,05×0,40×10 = 0,20 triệu USD trong mô hình một kỳ đơn giản.","id":"Q02-02","los_ids":["CFA26-08-03-LOS02"]},{"stem":"Nhận định nào phù hợp nhất về mezzanine debt?","options":["Luôn an toàn hơn nợ senior","Luôn có tài sản bảo đảm ưu tiên thứ nhất","Thường rủi ro hơn senior debt và có thể kèm warrants"],"correct_option":2,"explanation":"Mezzanine thường có thứ tự thu hồi thấp hơn senior, nên kỳ vọng coupon hoặc quyền chọn bổ sung để bù đắp rủi ro.","id":"Q02-03","los_ids":["CFA26-08-03-LOS02"]},{"stem":"Điều nào mô tả đúng lợi ích đa dạng hóa private capital?","options":["Lợi ích có thể có nếu biến động không đồng hướng hoàn toàn với tài sản truyền thống","Luôn xóa bỏ mọi rủi ro thị trường","Tương quan lịch sử luôn chính xác vì NAV định giá liên tục"],"correct_option":0,"explanation":"Private capital có thể có nguồn sinh lợi khác cổ phiếu/trái phiếu, nhưng tương quan biến đổi theo chu kỳ và NAV có thể bị smoothing.","id":"Q03-01","los_ids":["CFA26-08-03-LOS03"]},{"stem":"Vì sao đa dạng hóa theo vintage year hữu ích?","options":["Giảm thuế của tất cả quỹ về bằng 0","Tránh dồn toàn bộ cam kết vào một điều kiện thị trường và định giá","Bảo đảm mọi quỹ đều đạt IRR dương"],"correct_option":1,"explanation":"Dàn trải cam kết vào các vintage khác nhau giúp phân tán rủi ro của chu kỳ định giá và thời điểm triển khai vốn.","id":"Q03-02","los_ids":["CFA26-08-03-LOS03"]},{"stem":"Appraisal smoothing có thể làm chỉ số nào thấp giả tạo?","options":["Phí quản lý cam kết","Số lượng dự án trong quỹ","Biến động và tương quan quan sát được"],"correct_option":2,"explanation":"Định giá cập nhật chậm làm chuỗi lợi suất có vẻ trơn và ít phản ứng với thị trường hơn rủi ro kinh tế thực.","id":"Q03-03","los_ids":["CFA26-08-03-LOS03"]}],"flashcards":[{"front":"Khái niệm private equity — trình bày bản chất và công thức?","back":"Private equity là vốn chủ sở hữu cung cấp ngoài thị trường niêm yết, gồm đầu tư vào doanh nghiệp tư nhân hoặc thâu tóm doanh nghiệp niêm yết để đưa về tư nhân. Nhà đầu tư có thể nắm quyền kiểm soát hoặc phần vốn thiểu số; khả năng định giá, quản trị và thoái vốn quyết định kết quả, không thể chỉ dựa vào giá cổ phiếu tham chiếu.","id":"C01-01","los_ids":["CFA26-08-03-LOS01"]},{"front":"Venture capital qua các giai đoạn — trình bày bản chất và công thức?","back":"Venture capital hỗ trợ doanh nghiệp có tiềm năng tăng trưởng mạnh từ seed, startup, early-stage tới later-stage. Doanh thu và dòng tiền ban đầu có thể âm, xác suất thất bại lớn, đổi lại một số khoản đầu tư thành công có thể tạo giá trị rất cao. Khả năng pha loãng và nhu cầu nhiều vòng gọi vốn là rủi ro cốt lõi.","id":"C01-02","los_ids":["CFA26-08-03-LOS01"]},{"front":"Growth và developmental capital — trình bày bản chất và công thức?","back":"Growth capital hoặc minority equity thường hỗ trợ doanh nghiệp đã hình thành sản phẩm, có doanh thu và muốn mở rộng thị trường, tái cấu trúc hoặc thực hiện M&A. Nhà đầu tư có thể không kiểm soát toàn bộ hoạt động nên cần điều khoản bảo vệ cổ đông thiểu số, quyền thông tin và cơ chế thoái vốn phù hợp.","id":"C01-03","los_ids":["CFA26-08-03-LOS01"]},{"front":"Leveraged buyout và vai trò nợ vay — trình bày bản chất và công thức?","back":"LBO sử dụng đáng kể nợ cùng vốn chủ để mua doanh nghiệp có dòng tiền tương đối ổn định. Nếu cải thiện EBITDA và trả bớt nợ, equity value khi thoái vốn có thể tăng mạnh; ngược lại lãi vay, covenant breach và suy giảm EBITDA có thể khiến vốn chủ chịu tổn thất lớn. MBO do nhóm quản lý hiện hữu tham gia, MBI có nhóm quản lý bên ngoài.","id":"C01-04","los_ids":["CFA26-08-03-LOS01"]},{"front":"Private debt là gì — trình bày bản chất và công thức?","back":"Private debt là tín dụng được cung cấp trực tiếp hoặc qua quỹ cho người vay ngoài thị trường phát hành nợ công khai. Người cho vay phải tự thẩm định dòng tiền, collateral, quyền ưu tiên và covenant; rủi ro thanh khoản thường cao vì khoản vay không được giao dịch thường xuyên như trái phiếu niêm yết.","id":"C02-01","los_ids":["CFA26-08-03-LOS02"]},{"front":"Direct lending và senior secured debt — trình bày bản chất và công thức?","back":"Direct lending bao gồm khoản vay trực tiếp cho doanh nghiệp với kỳ hạn, lãi suất thường thả nổi và các covenant được đàm phán. Senior secured loans ưu tiên thu hồi từ tài sản bảo đảm trước chủ nợ cấp dưới, nhưng mức độ bảo vệ thực tế vẫn phụ thuộc tài sản, tính pháp lý và khả năng thực thi khi vỡ nợ.","id":"C02-02","los_ids":["CFA26-08-03-LOS02"]},{"front":"Leveraged lending và unitranche — trình bày bản chất và công thức?","back":"Leveraged loans tài trợ bên vay có đòn bẩy đáng kể, thường chịu rủi ro suy giảm khả năng trả nợ khi EBITDA giảm. Unitranche kết hợp nhiều lớp rủi ro nợ vào một khoản vay có hợp đồng và lãi suất tổng hợp; thỏa thuận giữa các nhà cho vay có thể phân chia thứ tự thu hồi nội bộ khác nhau.","id":"C02-03","los_ids":["CFA26-08-03-LOS02"]},{"front":"Mezzanine debt và quyền chuyển đổi — trình bày bản chất và công thức?","back":"Mezzanine financing nằm dưới nợ senior về thứ tự ưu tiên, thường có coupon cao hơn và có thể kèm warrants hoặc công cụ chuyển đổi. Bên cho vay nhận thêm phần thưởng tiềm năng khi doanh nghiệp phát triển, nhưng recovery khi vỡ nợ thường kém hơn senior secured debt.","id":"C02-04","los_ids":["CFA26-08-03-LOS02"]},{"front":"Lý thuyết đa dạng hóa private capital — trình bày bản chất và công thức?","back":"Private equity và private debt có nguồn sinh lợi khác nhau so với chứng khoán niêm yết, ví dụ tái cấu trúc doanh nghiệp, lãi suất vay tư nhân hoặc phát triển công ty sớm. Nếu tương quan với tài sản truyền thống chưa đạt +1, kết hợp tài sản có thể giảm biến động danh mục ở một số điều kiện.","id":"C03-01","los_ids":["CFA26-08-03-LOS03"]},{"front":"Tương quan phụ thuộc chu kỳ và loại chiến lược — trình bày bản chất và công thức?","back":"Venture capital, buyout, distressed debt và direct lending không có cùng mức độ tương quan với cổ phiếu/trái phiếu. Trong khủng hoảng dòng tiền và thanh khoản, beta kinh tế có thể tăng; không nên dùng tương quan lịch sử thấp như bằng chứng tài sản có khả năng phòng hộ mọi cú sốc.","id":"C03-02","los_ids":["CFA26-08-03-LOS03"]},{"front":"Valuation smoothing và kết quả quan sát — trình bày bản chất và công thức?","back":"NAV private capital được ghi nhận định kỳ từ mô hình hoặc thẩm định; do độ trễ, chuỗi lợi suất công bố thường có tương quan với thị trường thấp hơn quan hệ kinh tế thực tế. Phân tích danh mục cần cân nhắc việc làm mượt dữ liệu trước khi sử dụng historical correlation để đo lợi ích đa dạng hóa.","id":"C03-03","los_ids":["CFA26-08-03-LOS03"]},{"front":"Vintage year diversification — trình bày bản chất và công thức?","back":"Vintage year là năm quỹ bắt đầu triển khai đầu tư, có ý nghĩa vì điều kiện lãi suất, định giá và tăng trưởng doanh nghiệp thay đổi giữa các chu kỳ. Trải cam kết vốn qua nhiều vintage có thể giảm rủi ro đầu tư cùng lúc tại đỉnh định giá, nhưng không loại bỏ rủi ro hệ thống.","id":"C03-04","los_ids":["CFA26-08-03-LOS03"]}],"review_status":"targeted_CFAI_Kaplan_SAPP_math_and_browser_QA_not_exhaustive_full_PDF_verification"},{"module_id":"CFA26-08-04","title":"Real Estate and Infrastructure","version":"2026","source_basis":[{"source_id":"CFAI","pdf_pages":[101,128],"relation":"primary"},{"source_id":"Kaplan","pdf_pages":[35,42],"relation":"supplementary"},{"source_id":"SAPP","pdf_pages":[66,82],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-08-04-LOS01","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Giải thích đặc điểm và cấu trúc đầu tư bất động sản.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S01-01","S01-02","S01-03","S01-04","S01-05","S01-06","S01-07"],"formula_ids":["F01-01","F01-02"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V8_Alts_ONLINE.pdf","pdf_page":104},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":35},"SAPP_2026":{"file":"SAPP Alternative Investments.pdf","pdf_page":66}},"missing_items":[]},{"los_id":"CFA26-08-04-LOS02","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Giải thích đặc điểm đầu tư, nguồn lợi suất và rủi ro của bất động sản.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S02-01","S02-02","S02-03","S02-04","S02-05","S02-06","S02-07"],"formula_ids":["F02-01","F02-02"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V8_Alts_ONLINE.pdf","pdf_page":111},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":37},"SAPP_2026":{"file":"SAPP Alternative Investments.pdf","pdf_page":72}},"missing_items":[]},{"los_id":"CFA26-08-04-LOS03","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Giải thích đặc điểm và cấu trúc đầu tư cơ sở hạ tầng.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S03-01","S03-02","S03-03","S03-04","S03-05","S03-06","S03-07"],"formula_ids":["F03-01","F03-02"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V8_Alts_ONLINE.pdf","pdf_page":115},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":38},"SAPP_2026":{"file":"SAPP Alternative Investments.pdf","pdf_page":74}},"missing_items":[]},{"los_id":"CFA26-08-04-LOS04","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Giải thích đặc điểm đầu tư, nguồn lợi suất và rủi ro của cơ sở hạ tầng.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S04-01","S04-02","S04-03","S04-04","S04-05","S04-06","S04-07","S04-08"],"formula_ids":["F04-01","F04-02"],"example_ids":["E04-01","E04-02"],"question_ids":["Q04-01","Q04-02","Q04-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V8_Alts_ONLINE.pdf","pdf_page":123},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":39},"SAPP_2026":{"file":"SAPP Alternative Investments.pdf","pdf_page":79}},"missing_items":[]}],"sections":[{"heading_vi":"Real estate và các phân nhóm","body_vi":"Bất động sản bao gồm đất và công trình, thường chia thành nhà ở (residential) và thương mại (commercial) như văn phòng, bán lẻ, kho công nghiệp và khách sạn. Mỗi vị trí và loại tài sản có rủi ro cung–cầu, chất lượng người thuê, chi phí bảo dưỡng và thanh khoản khác nhau; không có một tỷ lệ lợi nhuận chung cho mọi dự án.","id":"S01-01","los_ids":["CFA26-08-04-LOS01"]},{"heading_vi":"Đầu tư trực tiếp và gián tiếp","body_vi":"Đầu tư trực tiếp mua quyền sở hữu hoặc quyền tham gia vào một tài sản cụ thể, có thể dùng nợ vay. Đầu tư gián tiếp qua private real estate funds, REIT hoặc chứng khoán của doanh nghiệp bất động sản; đổi lại quyền kiểm soát trực tiếp thường thấp hơn nhưng có thể giảm quy mô vốn tối thiểu và tăng đa dạng hóa.","id":"S01-02","los_ids":["CFA26-08-04-LOS01"]},{"heading_vi":"Equity và debt real estate","body_vi":"Equity investor chịu phần dư sau chi phí và trả nợ, hưởng tiền thuê lẫn tăng giá nhưng gánh lỗ đầu tiên. Debt investor nhận dòng coupon và gốc theo hợp đồng với quyền xử lý bảo đảm; senior mortgage thường ưu tiên hơn mezzanine debt, nhưng vẫn có rủi ro định giá collateral và default.","id":"S01-03","los_ids":["CFA26-08-04-LOS01"]},{"heading_vi":"REIT và cấu trúc phân phối","body_vi":"Real Estate Investment Trust (REIT) là phương tiện đầu tư sở hữu hoặc tài trợ bất động sản, có thể được niêm yết. Ở những hệ thống pháp luật đáp ứng điều kiện thu nhập và phân phối, REIT có thể hưởng cơ chế thuế qua chủ thể; phải tránh khẳng định ưu đãi thuế giống nhau ở mọi quốc gia.","id":"S01-04","los_ids":["CFA26-08-04-LOS01"]},{"heading_vi":"Dòng tiền cho thuê và NOI","body_vi":"Dòng tiền thường đến từ tiền thuê, tỷ lệ lấp đầy và tăng giá tài sản; chi phí hoạt động bao gồm vận hành, bảo dưỡng và quản lý. Net Operating Income (NOI) là thu nhập hoạt động ròng của bất động sản trước chi phí lãi vay và thuế thu nhập theo quy ước đơn giản; không đồng nhất NOI với dòng tiền tự do sau capex.","id":"S01-05","los_ids":["CFA26-08-04-LOS01"]},{"heading_vi":"Core, core-plus, value-add, opportunistic","body_vi":"Core tập trung tài sản chất lượng với khách thuê ổn định; core-plus chấp nhận một số cải thiện; value-add nâng cấp, tăng lấp đầy hoặc tái định vị; opportunistic có thể phát triển dự án hoặc tài sản gặp khó khăn. Rủi ro triển khai, nhu cầu vốn và biến động dòng tiền thường tăng từ core sang opportunistic.","id":"S01-06","los_ids":["CFA26-08-04-LOS01"]},{"heading_vi":"Tính địa phương và hạn chế thanh khoản","body_vi":"Bất động sản là tài sản không đồng nhất về vị trí, thiết kế và pháp lý; phí giao dịch, thời gian bán và yêu cầu quản lý dài hạn có thể lớn. REIT niêm yết thanh khoản hơn bất động sản trực tiếp nhưng giá có thể cùng biến động với thị trường cổ phiếu, nhất là khi lãi suất và kỳ vọng tăng trưởng đổi nhanh.","id":"S01-07","los_ids":["CFA26-08-04-LOS01"]},{"heading_vi":"Thu nhập vận hành và tăng giá","body_vi":"Tổng lợi suất BĐS đến từ tiền thuê và mức tăng/giảm giá bán theo thời gian. Với tài sản đang cho thuê, dòng tiền sau chi phí vận hành ảnh hưởng trực tiếp giá trị; giá có thể tăng khi thuê tăng hoặc cap rate giảm, nhưng đây không phải khoản lợi nhuận hiện thực hóa trước khi bán.","id":"S02-01","los_ids":["CFA26-08-04-LOS02"]},{"heading_vi":"Rủi ro vacancy và tenant credit","body_vi":"Tỷ lệ trống, khả năng trả tiền thuê của khách và tập trung người thuê quyết định độ ổn định NOI. Một tòa nhà chỉ có một khách thuê lớn có thể trông đầy công suất nhưng chịu rủi ro tập trung khi hợp đồng hết hạn hoặc khách phá sản; cần xét thời hạn thuê và lịch tăng giá.","id":"S02-02","los_ids":["CFA26-08-04-LOS02"]},{"heading_vi":"Chi phí bảo dưỡng, sửa chữa và capex","body_vi":"Bất động sản cần duy trì hệ thống kỹ thuật, sửa chữa, cải tạo và có thể chịu thuế đất hoặc phí bảo hiểm thay đổi. NOI chưa trừ toàn bộ capex; dòng tiền sẵn có cho chủ sở hữu có thể thấp đáng kể khi đến kỳ thay mái, thang máy hoặc tái phát triển.","id":"S02-03","los_ids":["CFA26-08-04-LOS02"]},{"heading_vi":"Lãi suất, cap rate và đòn bẩy","body_vi":"Giá trị vốn hóa có quan hệ nghịch với cap rate khi NOI không đổi. Lãi suất tài trợ tăng có thể làm chi phí vay và tỷ suất lợi nhuận yêu cầu tăng; với vị thế có đòn bẩy, tài sản giảm giá làm equity value giảm mạnh hơn tỷ lệ giảm của property value và có nguy cơ covenant breach.","id":"S02-04","los_ids":["CFA26-08-04-LOS02"]},{"heading_vi":"Lạm phát và điều khoản thuê","body_vi":"Tài sản có hợp đồng thuê gắn CPI hoặc được tăng giá định kỳ có thể bảo vệ một phần sức mua. Tuy nhiên chi phí vận hành và capex cũng tăng; khi hợp đồng dài hạn cố định danh nghĩa, giá thuê có thể không theo kịp lạm phát. Không coi mọi BĐS là phòng hộ lạm phát hoàn hảo.","id":"S02-05","los_ids":["CFA26-08-04-LOS02"]},{"heading_vi":"Đa dạng hóa và bất động sản niêm yết","body_vi":"BĐS trực tiếp có yếu tố thị trường địa phương và dòng thuê khác chứng khoán niêm yết, góp phần phân tán rủi ro ở một số điều kiện. Nhưng REIT niêm yết có thể có tương quan cao hơn với cổ phiếu; dữ liệu thẩm định BĐS trực tiếp có thể làm lợi suất báo cáo ít biến động giả tạo.","id":"S02-06","los_ids":["CFA26-08-04-LOS02"]},{"heading_vi":"Bậc thang rủi ro bất động sản","body_vi":"Senior mortgage thường có thứ tự thu hồi ưu tiên hơn nợ mezzanine và equity; với equity, core thường ít rủi ro triển khai hơn core-plus, value-add và opportunistic. Dù vậy, thứ tự không chắc chắn trong mọi trường hợp vì vị trí tài sản, hợp đồng thuê, cấu trúc nợ và giá mua quyết định tổn thất cuối cùng.","id":"S02-07","los_ids":["CFA26-08-04-LOS02"]},{"heading_vi":"Khái niệm và mục đích cơ sở hạ tầng","body_vi":"Infrastructure là tài sản dài hạn thiết yếu cho hoạt động kinh tế, xã hội như cảng, đường, điện, nước, mạng viễn thông, bệnh viện và trường học. Dự án thường cần vốn đầu tư lớn, thời gian xây dựng và khai thác dài, có tính đặc thù địa điểm và chịu quy định của cơ quan nhà nước hoặc hợp đồng nhượng quyền.","id":"S03-01","los_ids":["CFA26-08-04-LOS03"]},{"heading_vi":"Economic và social infrastructure","body_vi":"Economic infrastructure hỗ trợ sản xuất và lưu chuyển hàng hóa, gồm giao thông, năng lượng và viễn thông; social infrastructure phục vụ nhu cầu cộng đồng như trường học, cơ sở y tế và nhà ở xã hội. Cấu trúc thu nhập và đối tác trả tiền có thể khác nhau: doanh thu người sử dụng, ngân sách hoặc khoản thanh toán theo mức độ sẵn sàng.","id":"S03-02","los_ids":["CFA26-08-04-LOS03"]},{"heading_vi":"Greenfield, brownfield và secondary-stage","body_vi":"Greenfield bắt đầu với dự án mới, chịu rủi ro giải phóng mặt bằng, xây dựng, công nghệ và chậm tiến độ. Brownfield là tài sản đã hoặc đang hoạt động, thường ít rủi ro xây dựng hơn. Secondary-stage mô tả hạ tầng đã vận hành ổn định, không cần phát triển thêm lớn, có thể đem lại dòng tiền dự đoán được hơn.","id":"S03-03","los_ids":["CFA26-08-04-LOS03"]},{"heading_vi":"Availability-based và usage-based revenue","body_vi":"Availability payment trả cho việc giữ cơ sở hạ tầng sẵn sàng theo tiêu chuẩn dịch vụ, có thể kèm khấu trừ khi không đạt KPI; usage-based payment phụ thuộc lưu lượng, sản lượng hoặc số lượt sử dụng. Cả hai có rủi ro hợp đồng, nhưng usage-based nhạy với nhu cầu và chu kỳ kinh tế hơn nếu không có bảo lãnh.","id":"S03-04","los_ids":["CFA26-08-04-LOS03"]},{"heading_vi":"Nhượng quyền và PPP","body_vi":"Nhiều dự án triển khai qua concession, public–private partnership (PPP), hợp đồng xây dựng–vận hành–chuyển giao và cơ chế chia sẻ rủi ro với chính phủ. Nhà đầu tư phải đọc thời gian nhượng quyền, cơ chế điều chỉnh giá, nghĩa vụ bảo trì, tiêu chuẩn dịch vụ và rủi ro chấm dứt hợp đồng; không mặc định nhà nước luôn bảo lãnh nợ.","id":"S03-05","los_ids":["CFA26-08-04-LOS03"]},{"heading_vi":"Đầu tư trực tiếp, gián tiếp và trái phiếu hạ tầng","body_vi":"Đầu tư trực tiếp mua vốn chủ tài sản hoặc tham gia consortium với nhà vận hành chuyên môn; gián tiếp có thể qua quỹ, REIT hoặc doanh nghiệp niêm yết. Nhà đầu tư còn có thể mua nợ hoặc cho dự án vay. Quyền kiểm soát, thứ tự ưu tiên dòng tiền và thanh khoản khác nhau giữa equity và debt.","id":"S03-06","los_ids":["CFA26-08-04-LOS03"]},{"heading_vi":"Vòng đời và rủi ro vận hành","body_vi":"Sau giai đoạn phát triển, tài sản có thể cung cấp dịch vụ nhiều thập kỷ nhưng cần bảo dưỡng, đầu tư thay thế và tuân thủ quy định môi trường–an toàn. Lợi nhuận cuối cùng chịu tác động của khả năng tăng phí, chất lượng quản lý vận hành, chi phí năng lượng, tỷ giá và khả năng tái cấp vốn nợ.","id":"S03-07","los_ids":["CFA26-08-04-LOS03"]},{"heading_vi":"Nguồn lợi nhuận trong hạ tầng","body_vi":"Infrastructure có thể tạo dòng tiền dài hạn từ phí sử dụng, availability payment hoặc hợp đồng mua điện/dịch vụ. Lợi nhuận vốn chủ còn phụ thuộc giá bán khi thoái vốn, giảm nợ và thay đổi suất chiết khấu yêu cầu. Dòng thu nhập ổn định chỉ có khi đối tác trả tiền, cơ chế giá và vận hành đều đáp ứng hợp đồng.","id":"S04-01","los_ids":["CFA26-08-04-LOS04"]},{"heading_vi":"Các lớp rủi ro theo giai đoạn dự án","body_vi":"Greenfield có rủi ro phê duyệt, công nghệ, xây dựng và công suất ban đầu lớn hơn brownfield đang vận hành. Secondary-stage với tài sản khai thác hoàn chỉnh có thể ít biến động hơn, nhưng vẫn chịu rủi ro bảo dưỡng, thay thế thiết bị, nhu cầu và quy định. Không coi Brownfield không thể mất vốn.","id":"S04-02","los_ids":["CFA26-08-04-LOS04"]},{"heading_vi":"Rủi ro hợp đồng và đối tác mua dịch vụ","body_vi":"Hợp đồng dài hạn với chính phủ hoặc bên mua điện có thể giúp dự báo dòng tiền, nhưng vẫn có khả năng chậm thanh toán, tái đàm phán, thay đổi quy định và tranh chấp. Cần đánh giá chất lượng tín dụng của off-taker, điều khoản phạt, bảo lãnh và cơ chế giải quyết bất đồng.","id":"S04-03","los_ids":["CFA26-08-04-LOS04"]},{"heading_vi":"Rủi ro lãi suất, tái cấp vốn và tiền tệ","body_vi":"Dự án hạ tầng có đòn bẩy dài hạn nên tăng lãi suất làm chi phí nợ và tỷ lệ chiết khấu tăng. Nếu vay ngoại tệ còn doanh thu nội tệ, biến động tỷ giá có thể làm dòng tiền trả nợ thiếu hụt; hết hạn concession trước kỳ đáo hạn nợ cũng là rủi ro không thể bỏ qua.","id":"S04-04","los_ids":["CFA26-08-04-LOS04"]},{"heading_vi":"Bảo vệ lạm phát có điều kiện","body_vi":"Một số dự án có công thức điều chỉnh đơn giá theo CPI hoặc chi phí đầu vào, giúp bảo vệ một phần dòng tiền danh nghĩa. Khi tariff bị khống chế hoặc nhu cầu yếu, không thể chuyển hết lạm phát vào giá; đồng thời chi phí bảo trì và nhân công thường cũng tăng nhanh.","id":"S04-05","los_ids":["CFA26-08-04-LOS04"]},{"heading_vi":"Đa dạng hóa và tương quan thị trường","body_vi":"Dòng tiền dịch vụ thiết yếu có thể kém nhạy với chu kỳ so với tài sản thông thường, tạo lợi ích đa dạng hóa. Tuy nhiên tài sản niêm yết liên quan hạ tầng vẫn chịu biến động giá cổ phiếu và lãi suất; các dự án cùng khu vực có thể đồng thời chịu rủi ro điều tiết, thiên tai và nguồn vốn.","id":"S04-06","los_ids":["CFA26-08-04-LOS04"]},{"heading_vi":"So sánh nợ và vốn chủ dự án","body_vi":"Senior infrastructure debt ưu tiên dòng tiền thanh toán gốc/lãi, thường có lợi nhuận kỳ vọng thấp hơn vốn chủ. Equity hấp thụ tổn thất sau nợ nhưng hưởng upside từ vận hành và tăng giá; tầng mezzanine ở giữa. Tỷ lệ đòn bẩy và tính ổn định CFADS quyết định độ an toàn thực tế của mỗi tầng.","id":"S04-07","los_ids":["CFA26-08-04-LOS04"]},{"heading_vi":"Stress testing và tính bền vững dòng tiền","body_vi":"Đánh giá cần dự báo theo các kịch bản sản lượng thấp, tăng chi phí bảo trì, chậm điều chỉnh tariff, tăng lãi suất và chậm thanh toán từ bên mua. Hệ số DSCR dưới stress, covenant headroom và dự phòng bảo trì là thước đo thực tế hơn so với lợi suất dự phóng một kịch bản lạc quan.","id":"S04-08","los_ids":["CFA26-08-04-LOS04"]}],"formulae":[{"expression":"NOI = Rental and other property operating income − Property operating expenses","variables":["Không trừ lãi vay và thuế thu nhập theo định nghĩa NOI đơn giản."],"assumptions":["Tách capex định kỳ/capital reserve khỏi expenses theo quy ước bài toán."],"id":"F01-01","los_ids":["CFA26-08-04-LOS01"]},{"expression":"Cap rate = NOI stabilized / Property value; Property value ≈ NOI / Cap rate","variables":["NOI kỳ ổn định tương ứng với tỷ lệ vốn hóa thị trường."],"assumptions":["Không áp dụng máy móc khi thu nhập bất ổn hoặc có dự án đang xây dựng."],"id":"F01-02","los_ids":["CFA26-08-04-LOS01"]},{"expression":"Total property return ≈ (Net cash income + Ending property value − Beginning property value) / Beginning property value","variables":["Cùng một kỳ, không có nộp/rút vốn bổ sung hoặc điều chỉnh riêng."],"assumptions":["Bài toán đơn kỳ giản lược; thuế và chi phí chuyển nhượng có thể thay đổi kết quả."],"id":"F02-01","los_ids":["CFA26-08-04-LOS02"]},{"expression":"Loan-to-value (LTV) = Mortgage loan balance / Property market value","variables":["Dùng cùng ngày định giá và cùng đơn vị tiền."],"assumptions":["Không đồng nhất với debt service coverage hoặc khả năng trả nợ từ NOI."],"id":"F02-02","los_ids":["CFA26-08-04-LOS02"]},{"expression":"Usage-based revenue ≈ Tariff per unit × Units consumed","variables":["Đơn giá và sản lượng cùng kỳ, có thể cần điều chỉnh mức tối thiểu/khuyến mại."],"assumptions":["Ví dụ giản lược; tariff caps và thuế doanh thu có thể làm số thực nhận khác."],"id":"F03-01","los_ids":["CFA26-08-04-LOS03"]},{"expression":"DSCR = Cash flow available for debt service (CFADS) / Scheduled debt service","variables":["CFADS sau chi phí và các khoản giữ lại theo covenant; debt service gồm gốc và lãi đến hạn."],"assumptions":["Quy ước minh họa DSCR của dự án; không thay thế các định nghĩa hợp đồng khác nhau."],"id":"F03-02","los_ids":["CFA26-08-04-LOS03"]},{"expression":"Project equity value ≈ Enterprise value − Net debt","variables":["Giá trị tài sản và nợ ròng tại cùng thời điểm."],"assumptions":["Chưa xét thuế thoái vốn, nghĩa vụ ngoài bảng hoặc quyền cổ đông thiểu số."],"id":"F04-01","los_ids":["CFA26-08-04-LOS04"]},{"expression":"Traffic revenue change (%) ≈ New traffic/Old traffic − 1","variables":["Giả sử tariff bình quân không đổi và cấu trúc phương tiện tương đồng."],"assumptions":["Chỉ phù hợp dự án phí theo mức sử dụng, không áp dụng cho availability payment cố định."],"id":"F04-02","los_ids":["CFA26-08-04-LOS04"]}],"worked_examples":[{"problem":"Kho cho thuê tạo doanh thu ròng từ thuê 12 triệu/năm, chi phí vận hành 4 triệu, thị trường có cap rate 8%. Định giá đơn giản?","solution_steps":["NOI = 12−4 = 8 triệu/năm, chưa trừ lãi vay.","Giá trị ước tính = NOI/cap rate = 8/0,08 = 100 triệu.","Nếu cap rate tăng lên 10% với cùng NOI, giá trị giảm còn 80 triệu."],"answer":"Giá trị theo tỷ lệ vốn hóa khoảng 100 triệu; cap rate tăng 2 điểm % làm giá trị giảm khoảng 20 triệu.","id":"E01-01","los_ids":["CFA26-08-04-LOS01"]},{"problem":"Bất động sản văn phòng cho thuê toàn bộ giá trị 50 triệu, khoản vay senior 30 triệu. Tính LTV.","solution_steps":["LTV = dư nợ bảo đảm / giá trị tài sản = 30/50.","=0,60 = 60%.","Nếu giá tài sản giảm về 40 triệu mà dư nợ không đổi, LTV tăng thành 75%."],"answer":"LTV ban đầu 60%; khi tài sản giảm còn 40 triệu, LTV tăng lên 75%.","id":"E01-02","los_ids":["CFA26-08-04-LOS01"]},{"problem":"Nhà đầu tư mua BĐS giá 100, nhận dòng tiền sau chi phí 5 trong năm, cuối năm định giá 107. Tính total return.","solution_steps":["Thu nhập tiền mặt năm là 5.","Tăng giá chưa hiện thực hóa = 107−100 = 7.","Total return=(5+7)/100=12%, chưa tính thuế/chi phí thoái vốn."],"answer":"Total return xấp xỉ 12% gồm 5% thu nhập và 7% tăng giá tài sản.","id":"E02-01","los_ids":["CFA26-08-04-LOS02"]},{"problem":"Tòa nhà có NOI 9 triệu, value 90 triệu; nếu thị trường đòi cap rate từ10% lên12% và NOI giữ nguyên, giá trị mới?","solution_steps":["Giá trị cũ = NOI/cap rate = 9/0,10 = 90 triệu.","Giá trị mới = 9/0,12 = 75 triệu.","Giá trị giảm 15 triệu, tương đương 16,67% dù NOI không đổi."],"answer":"Giá trị giảm về 75 triệu; nhạy cảm với thay đổi cap rate.","id":"E02-02","los_ids":["CFA26-08-04-LOS02"]},{"problem":"Dự án đường thu phí có 2 triệu lượt xe/năm, giá thu bình quân 3 USD/lượt. Tính doanh thu usage-based đơn giản.","solution_steps":["Sản lượng dự tính = 2 triệu lượt.","Doanh thu = 2.000.000 × 3 USD = 6 triệu USD/năm.","Nếu lưu lượng giảm 20% khi mức phí không đổi, doanh thu còn 4,8 triệu USD/năm."],"answer":"Doanh thu dự tính 6 triệu USD/năm, nhạy trực tiếp với lưu lượng sử dụng.","id":"E03-01","los_ids":["CFA26-08-04-LOS03"]},{"problem":"Dự án điện có CFADS 15 triệu USD/năm, nghĩa vụ gốc lãi đến hạn 12 triệu. DSCR và ý nghĩa?","solution_steps":["CFADS theo giả định là 15 triệu.","DSCR = 15/12 = 1,25×.","DSCR>1 cho thấy dòng tiền kỳ này đủ trả nợ theo mô hình, nhưng chưa bảo đảm an toàn dưới kịch bản stress hoặc các kỳ khác."],"answer":"DSCR = 1,25×; cần stress test và so với điều kiện hợp đồng vay.","id":"E03-02","los_ids":["CFA26-08-04-LOS03"]},{"problem":"Dự án thu phí có doanh thu cơ sở 10 triệu/năm, lưu lượng giảm 30% nhưng đơn giá giữ nguyên. Doanh thu sau shock?","solution_steps":["Lưu lượng còn 70% mức ban đầu.","Doanh thu dự phóng = 10×0,70 = 7 triệu/năm.","Chi phí cố định vẫn phát sinh nên EBITDA và DSCR có thể giảm nhanh hơn 30%."],"answer":"Doanh thu còn 7 triệu/năm, giảm 3 triệu; cần tính tiếp khả năng trả nợ theo cấu trúc chi phí.","id":"E04-01","los_ids":["CFA26-08-04-LOS04"]},{"problem":"Dự án có EV 200 triệu, nợ ròng 140 triệu; trong stress EV giảm còn 170, nợ không đổi. So sánh equity value.","solution_steps":["Equity ban đầu = 200−140 = 60 triệu.","Equity sau stress = 170−140 = 30 triệu.","Tài sản EV giảm 15% nhưng equity value giảm 50% do đòn bẩy."],"answer":"Equity value giảm từ 60 xuống 30 triệu, tương đương 50% dù enterprise value chỉ giảm 15%.","id":"E04-02","los_ids":["CFA26-08-04-LOS04"]}],"questions":[{"stem":"Kho cho thuê có NOI 8 triệu mỗi năm và cap rate 8%; giá trị vốn hóa xấp xỉ?","options":["8 triệu","100 triệu","64 triệu"],"correct_option":1,"explanation":"Giá trị tài sản = NOI/cap rate = 8/0,08 = 100 triệu nếu NOI ổn định và cap rate phù hợp.","id":"Q01-01","los_ids":["CFA26-08-04-LOS01"]},{"stem":"Tài sản đang xây dựng và cần tái định vị lớn thường gần chiến lược nào hơn?","options":["Senior investment-grade mortgage","Core ổn định","Opportunistic"],"correct_option":2,"explanation":"Opportunistic chịu rủi ro phát triển hoặc tái cấu trúc lớn hơn core, nên tiềm năng lợi nhuận đi kèm khả năng tổn thất cao hơn.","id":"Q01-02","los_ids":["CFA26-08-04-LOS01"]},{"stem":"Nhận định đúng nhất về REIT niêm yết?","options":["Cung cấp tiếp cận BĐS thanh khoản hơn sở hữu trực tiếp nhưng giá có thể biến động theo cổ phiếu","Luôn có dòng tiền và thuế giống mọi nước","Không bao giờ chịu biến động thị trường cổ phiếu"],"correct_option":0,"explanation":"REIT có thể niêm yết, đa dạng hóa tài sản và dễ giao dịch hơn, nhưng vẫn chịu rủi ro giá chứng khoán và quy tắc thuế theo từng pháp luật.","id":"Q01-03","los_ids":["CFA26-08-04-LOS01"]},{"stem":"Tài sản giá100, tiền ròng năm5, giá cuối107; total return đơn giản?","options":["5%","12%","7%"],"correct_option":1,"explanation":"Lợi suất = [5+(107−100)]/100=12%, bao gồm cả thu nhập tiền và biến động giá chưa hiện thực hóa.","id":"Q02-01","los_ids":["CFA26-08-04-LOS02"]},{"stem":"Cap rate tăng từ10% lên12% trong khi NOI không đổi 9 triệu, giá trị vốn hóa mới?","options":["108 triệu","90 triệu","75 triệu"],"correct_option":2,"explanation":"Giá trị = NOI / cap rate = 9/0,12=75 triệu, thấp hơn mức 90 khi cap rate 10%.","id":"Q02-02","los_ids":["CFA26-08-04-LOS02"]},{"stem":"Rủi ro nào làm NOI của tòa nhà cho thuê dễ giảm?","options":["Khách thuê chủ lực không trả tiền và chấm dứt thuê","Hợp đồng thuê có khách đa dạng và chất lượng cao","Giảm vacancy của tòa nhà"],"correct_option":0,"explanation":"Vacancy và credit risk của tenant có thể làm dòng tiền thuê giảm, kéo giá trị bất động sản xuống.","id":"Q02-03","los_ids":["CFA26-08-04-LOS02"]},{"stem":"Điểm khác biệt căn bản của greenfield so với brownfield là gì?","options":["Brownfield chưa từng có tài sản hình thành","Greenfield thường chịu rủi ro xây dựng và hoàn thành dự án lớn hơn","Greenfield luôn có doanh thu ổn định sẵn"],"correct_option":1,"explanation":"Greenfield là dự án mới cần xây dựng nên có nguy cơ chậm tiến độ và vượt vốn; brownfield đã tồn tại hoặc đang khai thác.","id":"Q03-01","los_ids":["CFA26-08-04-LOS03"]},{"stem":"Trong usage-based infrastructure, doanh thu nhạy nhất với yếu tố nào khi đơn giá không đổi?","options":["Mệnh giá trái phiếu chính phủ","Số tầng của nhà tài trợ","Sản lượng/lưu lượng thực tế sử dụng"],"correct_option":2,"explanation":"Doanh thu phụ thuộc lượng người dùng/đơn vị dịch vụ, nên traffic hoặc usage biến động sẽ thay đổi dòng tiền.","id":"Q03-02","los_ids":["CFA26-08-04-LOS03"]},{"stem":"Dự án có CFADS 15 triệu và debt service 12 triệu; DSCR là?","options":["1,25×","0,8×","1,0×"],"correct_option":0,"explanation":"DSCR=15/12=1,25× theo CFADS và gốc/lãi đến hạn, nhưng vẫn cần đánh giá độ bền dòng tiền.","id":"Q03-03","los_ids":["CFA26-08-04-LOS03"]},{"stem":"Nhận định đúng nhất về nguồn lợi suất của tài sản hạ tầng?","options":["Luôn được chính phủ bảo lãnh toàn bộ","Có thể gồm dòng tiền hợp đồng và tăng giá vốn chủ khi thoái vốn","Chỉ đến từ bán lại chứng chỉ quỹ trong ngày"],"correct_option":1,"explanation":"Hạ tầng thường tạo dòng thu dài hạn từ hợp đồng/usage và có thể tăng giá tài sản; bảo lãnh nhà nước không mặc định tồn tại.","id":"Q04-01","los_ids":["CFA26-08-04-LOS04"]},{"stem":"Dự án có EV 200, nợ ròng 140; EV giảm còn 170, nợ giữ nguyên. Equity giảm bao nhiêu?","options":["30%","15%","50%"],"correct_option":2,"explanation":"Equity đầu = 60; sau = 30, giảm 30/60 = 50%; rủi ro vốn chủ khuếch đại khi dùng nợ.","id":"Q04-02","los_ids":["CFA26-08-04-LOS04"]},{"stem":"Bảo vệ chống lạm phát trong hợp đồng hạ tầng luôn đầy đủ?","options":["Không; phụ thuộc công thức tăng giá, trần phí và rủi ro nhu cầu","Đúng với mọi concession","Đúng vì chi phí bảo trì không thay đổi"],"correct_option":0,"explanation":"Ngay khi tariff có điều khoản indexation, giới hạn pháp lý, độ trễ và chi phí tăng có thể làm khả năng bảo vệ thực kém hơn kỳ vọng.","id":"Q04-03","los_ids":["CFA26-08-04-LOS04"]}],"flashcards":[{"front":"Real estate và các phân nhóm — trình bày bản chất và công thức?","back":"Bất động sản bao gồm đất và công trình, thường chia thành nhà ở (residential) và thương mại (commercial) như văn phòng, bán lẻ, kho công nghiệp và khách sạn. Mỗi vị trí và loại tài sản có rủi ro cung–cầu, chất lượng người thuê, chi phí bảo dưỡng và thanh khoản khác nhau; không có một tỷ lệ lợi nhuận chung cho mọi dự án.","id":"C01-01","los_ids":["CFA26-08-04-LOS01"]},{"front":"Đầu tư trực tiếp và gián tiếp — trình bày bản chất và công thức?","back":"Đầu tư trực tiếp mua quyền sở hữu hoặc quyền tham gia vào một tài sản cụ thể, có thể dùng nợ vay. Đầu tư gián tiếp qua private real estate funds, REIT hoặc chứng khoán của doanh nghiệp bất động sản; đổi lại quyền kiểm soát trực tiếp thường thấp hơn nhưng có thể giảm quy mô vốn tối thiểu và tăng đa dạng hóa.","id":"C01-02","los_ids":["CFA26-08-04-LOS01"]},{"front":"Equity và debt real estate — trình bày bản chất và công thức?","back":"Equity investor chịu phần dư sau chi phí và trả nợ, hưởng tiền thuê lẫn tăng giá nhưng gánh lỗ đầu tiên. Debt investor nhận dòng coupon và gốc theo hợp đồng với quyền xử lý bảo đảm; senior mortgage thường ưu tiên hơn mezzanine debt, nhưng vẫn có rủi ro định giá collateral và default.","id":"C01-03","los_ids":["CFA26-08-04-LOS01"]},{"front":"REIT và cấu trúc phân phối — trình bày bản chất và công thức?","back":"Real Estate Investment Trust (REIT) là phương tiện đầu tư sở hữu hoặc tài trợ bất động sản, có thể được niêm yết. Ở những hệ thống pháp luật đáp ứng điều kiện thu nhập và phân phối, REIT có thể hưởng cơ chế thuế qua chủ thể; phải tránh khẳng định ưu đãi thuế giống nhau ở mọi quốc gia.","id":"C01-04","los_ids":["CFA26-08-04-LOS01"]},{"front":"Thu nhập vận hành và tăng giá — trình bày bản chất và công thức?","back":"Tổng lợi suất BĐS đến từ tiền thuê và mức tăng/giảm giá bán theo thời gian. Với tài sản đang cho thuê, dòng tiền sau chi phí vận hành ảnh hưởng trực tiếp giá trị; giá có thể tăng khi thuê tăng hoặc cap rate giảm, nhưng đây không phải khoản lợi nhuận hiện thực hóa trước khi bán.","id":"C02-01","los_ids":["CFA26-08-04-LOS02"]},{"front":"Rủi ro vacancy và tenant credit — trình bày bản chất và công thức?","back":"Tỷ lệ trống, khả năng trả tiền thuê của khách và tập trung người thuê quyết định độ ổn định NOI. Một tòa nhà chỉ có một khách thuê lớn có thể trông đầy công suất nhưng chịu rủi ro tập trung khi hợp đồng hết hạn hoặc khách phá sản; cần xét thời hạn thuê và lịch tăng giá.","id":"C02-02","los_ids":["CFA26-08-04-LOS02"]},{"front":"Chi phí bảo dưỡng, sửa chữa và capex — trình bày bản chất và công thức?","back":"Bất động sản cần duy trì hệ thống kỹ thuật, sửa chữa, cải tạo và có thể chịu thuế đất hoặc phí bảo hiểm thay đổi. NOI chưa trừ toàn bộ capex; dòng tiền sẵn có cho chủ sở hữu có thể thấp đáng kể khi đến kỳ thay mái, thang máy hoặc tái phát triển.","id":"C02-03","los_ids":["CFA26-08-04-LOS02"]},{"front":"Lãi suất, cap rate và đòn bẩy — trình bày bản chất và công thức?","back":"Giá trị vốn hóa có quan hệ nghịch với cap rate khi NOI không đổi. Lãi suất tài trợ tăng có thể làm chi phí vay và tỷ suất lợi nhuận yêu cầu tăng; với vị thế có đòn bẩy, tài sản giảm giá làm equity value giảm mạnh hơn tỷ lệ giảm của property value và có nguy cơ covenant breach.","id":"C02-04","los_ids":["CFA26-08-04-LOS02"]},{"front":"Khái niệm và mục đích cơ sở hạ tầng — trình bày bản chất và công thức?","back":"Infrastructure là tài sản dài hạn thiết yếu cho hoạt động kinh tế, xã hội như cảng, đường, điện, nước, mạng viễn thông, bệnh viện và trường học. Dự án thường cần vốn đầu tư lớn, thời gian xây dựng và khai thác dài, có tính đặc thù địa điểm và chịu quy định của cơ quan nhà nước hoặc hợp đồng nhượng quyền.","id":"C03-01","los_ids":["CFA26-08-04-LOS03"]},{"front":"Economic và social infrastructure — trình bày bản chất và công thức?","back":"Economic infrastructure hỗ trợ sản xuất và lưu chuyển hàng hóa, gồm giao thông, năng lượng và viễn thông; social infrastructure phục vụ nhu cầu cộng đồng như trường học, cơ sở y tế và nhà ở xã hội. Cấu trúc thu nhập và đối tác trả tiền có thể khác nhau: doanh thu người sử dụng, ngân sách hoặc khoản thanh toán theo mức độ sẵn sàng.","id":"C03-02","los_ids":["CFA26-08-04-LOS03"]},{"front":"Greenfield, brownfield và secondary-stage — trình bày bản chất và công thức?","back":"Greenfield bắt đầu với dự án mới, chịu rủi ro giải phóng mặt bằng, xây dựng, công nghệ và chậm tiến độ. Brownfield là tài sản đã hoặc đang hoạt động, thường ít rủi ro xây dựng hơn. Secondary-stage mô tả hạ tầng đã vận hành ổn định, không cần phát triển thêm lớn, có thể đem lại dòng tiền dự đoán được hơn.","id":"C03-03","los_ids":["CFA26-08-04-LOS03"]},{"front":"Availability-based và usage-based revenue — trình bày bản chất và công thức?","back":"Availability payment trả cho việc giữ cơ sở hạ tầng sẵn sàng theo tiêu chuẩn dịch vụ, có thể kèm khấu trừ khi không đạt KPI; usage-based payment phụ thuộc lưu lượng, sản lượng hoặc số lượt sử dụng. Cả hai có rủi ro hợp đồng, nhưng usage-based nhạy với nhu cầu và chu kỳ kinh tế hơn nếu không có bảo lãnh.","id":"C03-04","los_ids":["CFA26-08-04-LOS03"]},{"front":"Nguồn lợi nhuận trong hạ tầng — trình bày bản chất và công thức?","back":"Infrastructure có thể tạo dòng tiền dài hạn từ phí sử dụng, availability payment hoặc hợp đồng mua điện/dịch vụ. Lợi nhuận vốn chủ còn phụ thuộc giá bán khi thoái vốn, giảm nợ và thay đổi suất chiết khấu yêu cầu. Dòng thu nhập ổn định chỉ có khi đối tác trả tiền, cơ chế giá và vận hành đều đáp ứng hợp đồng.","id":"C04-01","los_ids":["CFA26-08-04-LOS04"]},{"front":"Các lớp rủi ro theo giai đoạn dự án — trình bày bản chất và công thức?","back":"Greenfield có rủi ro phê duyệt, công nghệ, xây dựng và công suất ban đầu lớn hơn brownfield đang vận hành. Secondary-stage với tài sản khai thác hoàn chỉnh có thể ít biến động hơn, nhưng vẫn chịu rủi ro bảo dưỡng, thay thế thiết bị, nhu cầu và quy định. Không coi Brownfield không thể mất vốn.","id":"C04-02","los_ids":["CFA26-08-04-LOS04"]},{"front":"Rủi ro hợp đồng và đối tác mua dịch vụ — trình bày bản chất và công thức?","back":"Hợp đồng dài hạn với chính phủ hoặc bên mua điện có thể giúp dự báo dòng tiền, nhưng vẫn có khả năng chậm thanh toán, tái đàm phán, thay đổi quy định và tranh chấp. Cần đánh giá chất lượng tín dụng của off-taker, điều khoản phạt, bảo lãnh và cơ chế giải quyết bất đồng.","id":"C04-03","los_ids":["CFA26-08-04-LOS04"]},{"front":"Rủi ro lãi suất, tái cấp vốn và tiền tệ — trình bày bản chất và công thức?","back":"Dự án hạ tầng có đòn bẩy dài hạn nên tăng lãi suất làm chi phí nợ và tỷ lệ chiết khấu tăng. Nếu vay ngoại tệ còn doanh thu nội tệ, biến động tỷ giá có thể làm dòng tiền trả nợ thiếu hụt; hết hạn concession trước kỳ đáo hạn nợ cũng là rủi ro không thể bỏ qua.","id":"C04-04","los_ids":["CFA26-08-04-LOS04"]}],"review_status":"targeted_CFAI_Kaplan_SAPP_math_and_browser_QA_not_exhaustive_full_PDF_verification"}]);
